mapper.select:
SELECT a.`id`, a.`application_code`, a.`task_type`, a.`task_name`, a.`send_details`, a.`terminal_ids`,a.`send_status`,a.`send_result`,a.`third_record_id`, a.`tenant`,a.`deleted`,a.`create_by`,a.`creator_id`,a.`creator_type`, a.`create_time`, a.`update_by`,a.`updater_id`,a.`updater_type`, a.`update_time` FROM `command_dispatch_record` a where a.`deleted` = 0
and a.`application_code` = #{param.applicationCode}
and a.`task_type` = #{param.taskType}
and a.`task_name` like concat('%', #{param.taskName}, '%')
and a.`send_status` = #{param.sendStatus}
order by a.`create_time` DESC
